-- Helpers for turning and listing directions. The active helpers use 16 direction
-- values: north=0, east=4, south=8, west=12.

---
--- Generated by EmmyLua(https://github.com/EmmyLua)
--- Created by seancheey.
--- DateTime: 10/10/20 1:32 AM
---

local Vector2D = require("vector2d")
local ArrayList = require("array_list")

--- @class DirectionHelper
--- @type DirectionHelper
local DirectionHelper = {}
DirectionHelper.allStraightDirections = {
    defines.direction.north, defines.direction.east,
    defines.direction.south, defines.direction.west
}

-- Rotate a direction by this many units and wrap around the 16-value circle.
local function shift(direction, offset)
    return (direction + offset) % 16
end

--- @return defines.direction
-- Turn around by half a circle.
function DirectionHelper.reverseOf(direction)
    return shift(direction, 8)
end

--- @return defines.direction[]
-- Return the reverse direction and the two side directions; belts can receive input from these sides.
function DirectionHelper.listTailLeftRightOf(direction)
    return { shift(direction, 8), shift(direction, 4), shift(direction, 12) }
end

-- Return only the direction behind the piece, wrapped in a list.
function DirectionHelper.listReverseOf(direction)
    return { DirectionHelper.reverseOf(direction) }
end

-- Return only the forward direction, wrapped in a list.
function DirectionHelper.listFrontOf(direction)
    return { direction }
end

-- Return all four cardinal directions; a surface pipe can connect on any side.
function DirectionHelper.listAllStraightDirectionOf(direction)
    return DirectionHelper.allStraightDirections
end

--- @param entity LuaEntity
--- @return Vector2D
-- Find the tile directly in front of this entity.
function DirectionHelper.targetPositionOf(entity)
    return DirectionHelper.targetPosition(entity.position, entity.direction)
end

--- @param position Vector2D
--- @param direction defines.direction
--- @return Vector2D
-- Move one tile from a position in the supplied direction.
function DirectionHelper.targetPosition(position, direction)
    return Vector2D.fromPosition(position) + Vector2D.fromDirection(direction or defines.direction.north)
end

--- @param position Vector2D
--- @param getEntityFunc fun()
--- @return LuaEntity[] | ArrayList
-- Ask the supplied lookup function for transport pieces on the four neighboring tiles.
function DirectionHelper.neighboringEntities(position, getEntityFunc)
    local entities = ArrayList.new()
    for _, direction in ipairs { defines.direction.north, defines.direction.east, defines.direction.south, defines.direction.west } do
        local entity = getEntityFunc(Vector2D.fromDirection(direction) + position)
        if entity ~= nil then
            entities:add(entity)
        end
    end
    return entities
end

return DirectionHelper
